// Auto-generated from diagnosis_3.html
// Run: npm start
// Open the forwarded Codespaces port (default 3000).

const http = require('http');
const url = require('url');

const PORT = Number(process.env.PORT || 3000);
const HOST = process.env.HOST || '0.0.0.0';

// The original HTML/CSS/browser-JavaScript page is embedded here so this
// repository can run from a single executable Node.js file.
const PAGE_HTML = Buffer.from(
  '',
  'base64'
).toString('utf8');

const server = http.createServer((req, res) => {
  const pathname = url.parse(req.url).pathname;

  if (pathname === '/health') {
    res.writeHead(200, {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'no-store'
    });
    res.end(JSON.stringify({ status: 'ok', service: 'medical-history-demo' }));
    return;
  }

  if (pathname === '/' || pathname === '/index.html') {
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer'
    });
    res.end(PAGE_HTML);
    return;
  }

  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('404 - Not Found');
});

server.listen(PORT, HOST, () => {
  console.log(`Medical History demo running on http://${HOST}:${PORT}`);
  console.log('In GitHub Codespaces, open the forwarded port shown in the Ports tab.');
});

process.on('SIGTERM', () => server.close(() => process.exit(0)));
process.on('SIGINT', () => server.close(() => process.exit(0)));
